        self.assertEqual(parse_money(3), Decimal("3.00"))

    def test_negative_raises(self):
        with self.assertRaises(ValueError):
            parse_money("-1")

    def test_non_numeric_raises(self):
        for bad in ("abc", None, "nan"):
            with self.assertRaises(ValueError):
                parse_money(bad)


