        self.assertEqual(line_total("5.00", 0), Decimal("0.00"))

    def test_bool_quantity_rejected(self):
        with self.assertRaises(ValueError):
            line_total("1", True)

    def test_negative_quantity_rejected(self):
        with self.assertRaises(ValueError):
            line_total("1", -1)

    def test_float_quantity_rejected(self):
        with self.assertRaises(ValueError):
            line_total("1", 1.5)


